    module_season_id = 1,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "After helping you straighten out your thoughts, Victor offered to hear your report in advance. After repeated discussions with your colleagues, you decided to create an online show to show off your company's strength."
  },
  [1405] = {
    module_page_id = 1014,
    order_in_page = 5,
    module_unlock_request = 11025,
    module_unlock_request_desc = "Clear 10-15 to unlock",
    module_vol_id = 101,
    module_season_id = 1,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "After some consideration, you decided on the topic of food. Several trips later, you excitedly came to the restaurant Kiro mentioned on the phone—Souvenir."
  },
  [1406] = {
    module_page_id = 1014,
    order_in_page = 6,
    module_unlock_request = 11025,
    module_unlock_request_desc = "Clear 10-15 to unlock",
    module_vol_id = 101,
    module_season_id = 1,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "The restaurant was small and mysterious—It didn't have regular business hours. You hadn't managed to get in several times. It was only five days later when you finally managed to talk to the waiter, Mr. Mills, and entered the restaurant."
  },
  [1407] = {
    module_page_id = 1014,
    order_in_page = 7,
    module_unlock_request = 11025,
    module_unlock_request_desc = "Clear 10-15 to unlock",
    module_vol_id = 101,
    module_season_id = 1,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "To your surprise, despite its small area, the environment reflected the owner's extraordinary taste. You couldn't wait to ask for an interview, but the mysterious owner asked Mr. Mills to pass on his \"no photography\" principle: \"I have the right to choose my customers. I don't welcome people who come to this restaurant for anything other than food.\""
  },
  [1408] = {
    module_page_id = 1014,
    order_in_page = 8,
    module_unlock_request = 11025,
    module_unlock_request_desc = "Clear 10-15 to unlock",
    module_vol_id = 101,
    module_season_id = 1,
    module_type = 1,
    module_is_pic = 1,
    module_connect_id = 1409,
    module_to_module_delay = 0.5,
    module_delay = 2,
    module_desc = "You were told to leave Souvenir by Mr. Mills apologetically, which made you frustrated and upset. At this moment, someone gently tapped on your shoulder. You turned around in surprise and met Kiro's smiling eyes—He hurried over as soon as hearing that you were at Souvenir. With his help in negotiating, you finally managed to get a chance to dine there."
  },
  [1409] = {
    module_page_id = 1014,
    order_in_page = 9,
    module_unlock_request = 11025,
    module_unlock_request_desc = "Clear 10-15 to unlock",
    module_vol_id = 101,
    module_season_id = 1,
    module_type = 2,
    module_desc = "\"The boss always makes sure the food is served at just the right temperature. Let's dig in.\"",
    role1 = 301000,
    role2 = 301101,
    role3 = 301201,
    module_role_zoom_rate = 0.5,
    module_remove = "'0,-200",
    module_background_id = 1281,
    module_voice = "voice_100404_56.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [1410] = {
