    order_in_page = 10,
    module_unlock_request = 11025,
    module_unlock_request_desc = "Clear 10-15 to unlock",
    module_vol_id = 101,
    module_season_id = 1,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "All your negative emotions were swept away the moment you tasted the food at Souvenir: The food here was unbelievably delicious."
  },
  [1411] = {
    module_page_id = 1014,
    order_in_page = 11,
    module_unlock_request = 11025,
    module_unlock_request_desc = "Clear 10-15 to unlock",
    module_vol_id = 101,
    module_season_id = 1,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "After your meal, you received a special bill, asking you to stay and wash the dishes. You could see how unusual the owner was and wanted to interview this restaurant even more. Yet the owner was nowhere to be seen when you entered the kitchen. The only thing left was the pudding in the oven, quietly filling the room with an appetizing aroma."
  },
  [1412] = {
    module_page_id = 1014,
    order_in_page = 12,
    module_unlock_request = 11025,
    module_unlock_request_desc = "Clear 10-15 to unlock",
    module_vol_id = 101,
    module_season_id = 1,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "Despite feeling disappointed, you left your contact information, hoping that the owner would see it and agree to your request for an interview."
  },
  [1413] = {
    module_page_id = 1014,
    order_in_page = 13,
    module_unlock_request = 11025,
