    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "After the interview, Mr. Mills gave you a pudding on behalf of the owner—It was strange that the owner never showed up even though he was in the restaurant."
  },
  [1416] = {
