    module_vol_id = 101,
    module_season_id = 1,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "Sensing your unease, Victor thoughtfully checked if you were okay. You told him that you seemed to have seen a similar place when you were a child and mentioned being saved by an older boy. Victor stared at you silently and seemed to be deep in thought."
  },
  [11019] = {
