    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "A brilliant flash was followed by deafening thunder as a bolt of lightning streaked toward Victor. You instinctively dived over to shield him behind you. The last thing you saw was Victor's shaking face from pain and shock."
  },
