    module_to_module_delay = 0.5,
    module_desc = "At this point, Gavin got in touch with the Special Task Force. Through the information he provided, you learned about the underground situation under Rock Reef and speculated that there might be clues related to Lighthouse there, so you volunteered to go along."
  },
  [50205] = {
