    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "The next day, you and Gavin tried out the machine as a media party. In his fond memories, you saw him, and yourself, in high school—when those eyes never met, hiding those youthful and heartfelt secrets."
  },
  [60109] = {
    module_page_id = 2062,
    order_in_page = 9,
