  },
  [70111] = {
    module_page_id = 2072,
    order_in_page = 11,
    module_unlock_request = 312515,
    module_unlock_request_desc = "Clear 25-15 to unlock",
    module_vol_id = 207,
    module_season_id = 2,
    module_type = 1,
    module_is_pic = 1,
    module_connect_id = 70112,
    module_to_module_delay = 0.5,
    module_delay = 2,
    module_desc = "After emitting the [c][f78585]Evol particles[-][/c], you two sat on the steps in the park where he fell asleep on you. You were distressed to see him being exhausted and hoped that there would be fewer storms so that he could sleep peacefully on your shoulder. You also secretly hoped that he would be more selfish, to which he replied that he was carrying out his duty."
  },
  [70112] = {
