    module_unlock_request = 312515,
    module_unlock_request_desc = "Clear 25-15 to unlock",
    module_vol_id = 207,
    module_season_id = 2,
    module_type = 3,
    module_desc = "\"Someone has to make the sacrifice to solve the crisis.\"",
    module_card_id = 54541,
