    module_season_id = 2,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "Before saying goodbye, Gavin told you that [c][f78585]Core[-][/c] was in his hands and told you not to do anything dangerous until you next meet again."
  },
  [70114] = {
