    module_vol_id = 207,
    module_season_id = 2,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "The next morning, you attended [c][f78585]BS's meeting[-][/c] on time, which was not very pleasant. After you left the BS building, the car you were driving was controlled by a pair of hands that appeared out of nowhere, and you ended up falling into the sea."
  },
  [70203] = {
