  [70302] = {
    module_page_id = 2074,
    order_in_page = 2,
    module_unlock_request = 312515,
    module_unlock_request_desc = "Clear 25-15 to unlock",
    module_vol_id = 207,
    module_season_id = 2,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "You woke up at night, straightened out your thoughts, and contacted numerous media partners overnight, asking them to debunk the rumors about the [c][f78585]radiation[-][/c] and [c][f78585]meteor shower[-][/c]. After hanging up, your phone flashed black again. A scene appeared before your eyes—Victor lying in the middle of a ruin. Shocked and worried, you headed to Victor's home to see what was going on. The door was opened, but no one was home."
  },
  [70303] = {
    module_page_id = 2074,
    order_in_page = 3,
    module_unlock_request = 312515,
    module_unlock_request_desc = "Clear 25-15 to unlock",
    module_vol_id = 207,
    module_season_id = 2,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "The Victor from the past [c][f78585] traveled through time [-][/c] and came to the present. Under the intense pressure, he still managed to open the door for you. He was warned that he would be punished for breaking the rules repeatedly, but he didn't care."
  },
  [70304] = {
    module_page_id = 2074,
    order_in_page = 4,
    module_unlock_request = 312515,
    module_unlock_request_desc = "Clear 25-15 to unlock",
    module_vol_id = 207,
    module_season_id = 2,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "When you were searching around Victor's home, he appeared with a thin layer of sweat on his forehead. Although you felt that something didn't seem right, he convinced you by saying it was a \"test of your judgment\". You shared information with him about the [c][f78585]meteor shower[-][/c] and [c][f78585]Lighthouse[-][/c] and he also found out that you were almost killed."
  },
  [70305] = {
    module_page_id = 2074,
    order_in_page = 5,
    module_unlock_request = 312515,
    module_unlock_request_desc = "Clear 25-15 to unlock",
    module_vol_id = 207,
    module_season_id = 2,
    module_type = 1,
    module_is_pic = 1,
    module_connect_id = 70306,
    module_to_module_delay = 0.5,
    module_delay = 6,
    module_desc = "A few days later at the council of the [c][f78585]Twelve Deities of Black Swan[-][/c], Victor wore a badge with a mini camera on his chest for you to watch the meeting remotely. At the meeting, Victor used the news of your [c][f78585] \"faked death\"[-][/c] to find out the person who tried to murder you. Eventually, Thanatos committed suicide by swallowing pills. At night, you stayed overnight in the guest room of Victor's house, and he brought you a glass of milk."
  },
  [70306] = {
    module_page_id = 2074,
    order_in_page = 6,
    module_unlock_request = 312515,
    module_unlock_request_desc = "Clear 25-15 to unlock",
    module_vol_id = 207,
