    module_to_module_delay = 0.5,
    module_delay = 3,
    module_desc = "You told him about the terrifying image you saw—him lying in the ruin. He lied down and fell asleep with you to comfort you."
  },
  [70308] = {
    module_page_id = 2074,
    order_in_page = 8,
    module_unlock_request = 312515,
    module_unlock_request_desc = "Clear 25-15 to unlock",
    module_vol_id = 207,
    module_season_id = 2,
