  [70309] = {
    module_page_id = 2074,
    order_in_page = 9,
    module_unlock_request = 312515,
    module_unlock_request_desc = "Clear 25-15 to unlock",
    module_vol_id = 207,
    module_season_id = 2,
    module_type = 1,
    module_is_pic = 1,
    module_to_module_delay = 0.5,
    module_desc = "When you woke up again, Victor had already made you breakfast. During your conversation, you two realized what was suspicious about the rumor of the [c][f78585]starlight[-][/c] and [c][f78585]radiation[-][/c] and decided to return to when the meteor shower[c][f78585]first[-][/c] appeared. You then found that the clues were pointing to the BS building. Back in reality, Victor seemed to already have a plan. At night, you saw from behind that Victor was in pain in the kitchen. Yet he said nothing but gave you a pudding."
  },
  [70310] = {
    module_page_id = 2074,
    order_in_page = 10,
    module_unlock_request = 312515,
    module_unlock_request_desc = "Clear 25-15 to unlock",
    module_vol_id = 207,
    module_season_id = 2,
    module_type = 1,
    module_is_pic = 1,
    module_connect_id = 70311,
    module_to_module_delay = 0.5,
    module_delay = 7,
    module_desc = "You returned to the BS building once again to attend the council of the [c][f78585]Twelve Deities of Black Swan[-][/c]. This time, Victor revealed his identity in front of everyone! He expelled some of the [c][f78585]BS radicals[-][/c] and even including you. After the meeting, you wanted to ask him the reason, but the BS building started to collapse! Victor paused time for you to escape. But you saw the image of Victor being injured again and couldn't help but fall to your knees. A great repulsion came flooding at you. You heard Victor's voice and saw him reaching out to you."
  },
  [70311] = {
