  [80102] = {
    module_page_id = 2075,
    order_in_page = 2,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You awoke in a daze. To your shock, you and Victor are now in a completely strange place. Your last conscious memories were of Victor being consumed by a large black vortex inside the BS building. He informed you that it was some kind of spacial rift. As you two planned your escape, [c][f78585]Time Observer Zero[-][/c] appeared and brought you to the [c][f78585]Spacetime Bureau[-][/c]. You couldn't help but notice Victor and the Time Observer seemed to know each other. The Time Observer claimed that fixing up the BS Explosion Case was supposed to be his job, but Victor beat him to it. Zero was vague when asked about the vortex and only mentioned a \"cost\"."
  },
  [80103] = {
    module_page_id = 2075,
    order_in_page = 3,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
