    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Zero modified Victor's [c][f78585]pocket watch[-][/c] so that the vortex could no longer find him. The caveat was that he was now forbidden to use Evol. Victor said that he wanted a private word with Zero."
  },
  [80104] = {
