  },
  [80126] = {
    module_page_id = 2075,
    order_in_page = 26,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Shaw pretended to have been bested by you. After making sure he was safe and conscious, you handed him over to GR and passed their [c][f78585]test[-][/c]."
  },
  [80201] = {
    module_page_id = 2076,
    order_in_page = 1,
