    module_type = 1,
    module_connect_id = 80217,
    module_to_module_delay = 0.5,
    module_delay = 3,
    module_desc = "After the successful operation, you had to leave in a hurry as Savin called you back to the office for exigence. Halfway there, Kiro suddenly appeared and agreed to the Publicity Department's proposal and told you that he was now fully healed."
  },
