    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "During break time, Anna showed you a video where the building you held the dance in went ablaze. You arrived on the scene but could not find any traces of burning."
  },
  [80219] = {
    module_page_id = 2076,
    order_in_page = 19,
    module_unlock_request = 312915,
