    module_to_module_delay = 0.5,
    module_desc = "Inside [c][f78585]NW's office[-][/c], Silas discussed the recent information leak with Lucien."
  },
  [80303] = {
    module_page_id = 2077,
    order_in_page = 3,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "They planned to use Lucien as bait to draw out the [c][f78585]\"mole\"[-][/c]."
  },
  [80304] = {
    module_page_id = 2077,
    order_in_page = 4,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You came up with a new proposal after abandoning the old one for Miracle Finder. Feeling uneasy and unsure, you decided to take a walk. However, you inadvertently arrived at the [c][f78585]Bioscience Research Center[-][/c]. Lucien seemed to know you were coming and greeted you as he gave you plenty of valuable advice. With his guidance, you regained your confidence. You asked Lucien to appear in the show, and he happily obliged."
  },
  [80305] = {
    module_page_id = 2077,
    order_in_page = 5,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 80306,
    module_to_module_delay = 0.5,
    module_delay = 8,
    module_desc = "After a few days, you arrived at the [c][f78585]shooting location[-][/c] and met up with Lucien with your new script. This place was the first hospital to admit Evolvers after the New Year Coup. While shooting, someone suddenly attacked you. To avoid collateral damage, you quickly left the filming location. You had not anticipated someone would go this far to sabotage the filming. Lucien could not help but remind you."
  },
  [80306] = {
    module_page_id = 2077,
