    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Lucien left for a while after taking a phone call. Feeling uneasy, you dialed his number."
  },
  [80309] = {
    module_page_id = 2077,
    order_in_page = 9,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
