    module_connect_id = 80310,
    module_to_module_delay = 0.5,
    module_delay = 3,
    module_desc = "Inside the washroom, Lucien strafed left and right as he dodged the incoming attacks. He told you it was nothing serious. After realizing your worries about the fight getting out of control, he replied."
  },
  [80310] = {
