    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You arrived at the Publicity Department after your sample clip was rejected. Here, you unexpectedly ran into Leto. This was the first time you met him after the rewind. Apprehensive, you reluctantly agreed to delete the scenes about the [c][f78585]New Year Coup[-][/c] in order to guarantee the film's airing. After the meeting, you received a phone call from Eli asking you to take Gavin out on a \"date\"."
  },
  [80403] = {
    module_page_id = 2078,
    order_in_page = 3,
