    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Inside Gavin's office, you saw an exhausted Gavin working tirelessly. The long stream of malicious cases has driven him to the brink. You decided to give him a change of pace and took him out on a date."
  },
  [80404] = {
    module_page_id = 2078,
    order_in_page = 4,
    module_unlock_request = 312915,
