    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 80405,
    module_to_module_delay = 0.5,
    module_delay = 3,
    module_desc = "Arriving at [c][f78585]Memorial Square[-][/c], a young man accused Gavin of negligence and swung fast at him. Gavin did not move out of the way, instead promising to give everyone a proper closure."
  },
  [80405] = {
    module_page_id = 2078,
