    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 2,
    module_desc = "\"I give you my word on my life.\"",
    role1 = 498000,
    role2 = 402107,
