  [80406] = {
    module_page_id = 2078,
    order_in_page = 6,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 80407,
    module_to_module_delay = 0.5,
    module_delay = 10,
    module_desc = "Leaving the square, you arrived at a residential area. You soon realized that the peaceful atmosphere was just a facade as Gavin confirmed your worries. Many attacks happening in Loveland City had been covered up. To give people hope and courage, the Special Task Force headed by Gavin was in an arduous effort. You suddenly realized how much stress Gavin was under. He confided in you and told you that something was worrying him."
  },
  [80407] = {
    module_page_id = 2078,
    order_in_page = 7,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"But I forgot that you're bound to fail if you're scared of failing.\"",
    module_card_id = 54571,
    module_CG_zoom = 0.83,
    module_remove = "'0,-190",
    module_voice = "voice_122905_62.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [80408] = {
    module_page_id = 2078,
    order_in_page = 8,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You encouraged Gavin as you told him to be brave and do what he wants to do."
  },
  [80409] = {
    module_page_id = 2078,
    order_in_page = 9,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You arrived at the Special Task Force to aid in the investigation of the Evolver who was following you. Instead, Tang took you to the training ground where you saw Gavin and Eli wrestled together. From their conversation, you learned that the undisclosed [c][f78585]Chief Commander of the Special Task Force[-][/c] was none other than [c][f78585]Gavin[-][/c]. You also learned of his frustration and anger after he sneaked into the BS building but failed to apprehend the culprit."
  },
  [80410] = {
    module_page_id = 2078,
    order_in_page = 10,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After Eli and the others left, Gavin took you back to his place and asked you to lock him up since he needed space to think everything over. You bought a [c][f78585]wind chime[-][/c] in the hopes that it'll accompany Gavin and bring home solace and encouragement."
  },
  [80411] = {
    module_page_id = 2078,
    order_in_page = 11,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 80412,
    module_to_module_delay = 0.5,
    module_delay = 5,
    module_desc = "Gavin sat inside his home the entire day as he felt lighter and lighter, but the sound of the [c][f78585]wind chime[-][/c] pulled him back to reality. He knew he was running out of time. Knowing that he might disappear at any minute, he wrote you a letter as he did before, knowing that you did not like a silent farewell."
  },
  [80412] = {
    module_page_id = 2078,
    order_in_page = 12,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"Please give me some more time.\"",
    module_card_id = 54570,
    module_CG_zoom = 0.83,
    module_remove = "'0,-200",
    module_voice = "voice_122907_50.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [80413] = {
    module_page_id = 2078,
    order_in_page = 13,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "At the same time, you picked up a phone call from GR telling you that someone was planning to sabotage the [c][f78585]CORE[-][/c] at the [c][f78585]Memorial Square[-][/c] tonight. You ran into Gavin and received his delayed letter. He told you that he plans to catch them all this time."
  },
  [80414] = {
    module_page_id = 2078,
    order_in_page = 14,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You and members of GR hid near [c][f78585]Memorial Square[-][/c] as Gavin confronted Dionysus and his goons. To prevent the [c][f78585]CORE[-][/c] from falling into the hands of BS, the GR members decided to attack. Chaos ensued in the square. As you secretly helped Gavin, suddenly, you realize that there were also members of NW present in this conflict fighting with Gavin. Throughout the entire struggle, Gavin acted as if he was waiting for something. Finally, after a few brief flickers of light from afar, Gavin cracked the box containing the [c][f78585]CORE[-][/c] in half. Meanwhile, the entire square was surrounded by men from the Special Task Force."
  },
  [80415] = {
    module_page_id = 2078,
    order_in_page = 15,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 80416,
    module_to_module_delay = 0.5,
    module_delay = 3,
    module_desc = "You finally met up with Gavin. Your heart throbbed as the exhaustion was clearly visible on Gavin's face. Gavin acted as if he had something to say, but in the end, he only said a few farewell words."
  },
  [80416] = {
    module_page_id = 2078,
    order_in_page = 16,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 2,
    module_desc = "\"You don't have to read the letter I gave you tonight anymore.\"",
    role1 = 4103000,
    role2 = 403106,
    role3 = 403203,
    role5 = 4103401,
    module_role_zoom_rate = 0.5,
    module_remove = "'0,-200",
    module_background_id = 1113,
    module_voice = "voice_122910_45.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [80417] = {
    module_page_id = 2078,
    order_in_page = 17,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After parting ways with you, Gavin felt his vision blur as he sat in the car. He knew he was fading, and he couldn't bring himself to say goodbye to you. As he slowly vanished, he made Eli promise him that none of the guilty shall go unpunished."
  },
  [80418] = {
    module_page_id = 2078,
    order_in_page = 18,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Upon returning home, you read Gavin's letter. In it, he asked you to meet him tomorrow at the [c][f78585]library[-][/c]. The very next day, you waited for a long time at the [c][f78585]library[-][/c], but Gavin never showed up. As you turned around to leave, a familiar breeze surrounded you. It was faint but felt strangely familiar."
  },
  [80419] = {
    module_page_id = 2078,
    order_in_page = 19,
    module_unlock_request = 312915,
    module_unlock_request_desc = "Clear 29-15 to unlock",
    module_vol_id = 208,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "An almost transparent Gavin lay in an [c][f78585]enclosed laboratory[-][/c] as the members of NW conducted their experiment under his agreement."
  },
  [90101] = {
