  [90102] = {
    module_page_id = 2079,
    order_in_page = 2,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "In NW's secret laboratory, the screen on the equipment showed that the [c][f78585]test subject[-][/c] evolution progress had reached 96%. The laboratory was suddenly under an explosion attack. The vibration was felt in the office nearby, yet Lucien continued to read his experiment reports unconcernedly."
  },
  [90103] = {
    module_page_id = 2079,
    order_in_page = 3,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After escaping from the [c][f78585]Memorial Square[-][/c] operation, you were interrogated by GR. But Doven ended the interrogation abruptly when something seemed to have come up. Carrying a teleportation device, you sneaked into an office to investigate the mechanical box, only to find Doven suddenly walking in. You hid behind the curtains and found that the person who came in with Doven was none other than Helios."
  },
  [90104] = {
    module_page_id = 2079,
    order_in_page = 4,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Helios seemed to be working with Doven. They mentioned the [c][f78585]NW experiment[-][/c] in their conversation. Helios spotted you hiding behind the curtains and helped to cover you up while probing on Doven, which showed that GR had nothing to do with the [c][f78585]mechanical box[-][/c] and that they were plotting on eliminating Evolvers. Soon enough, Helios reminded you to leave using the device, then he soon followed after you."
  },
  [90105] = {
