    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"He might not be by my side, but he would always share this joy with me.\"",
