  [90107] = {
    module_page_id = 2079,
    order_in_page = 7,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "When you woke up the next day, Kiro received a help request from a fan—Her grandpa who suffered from motor neuron disease was in dire need of a blood transfusion. You both rushed to the hospital to solve the problem for now. But soon, you found out something strange—all the patients who needed blood transfusions were Evolvers and were diagnosed with [c][f78585]blood disease[-][/c]. You began to sense that something wasn't right."
  },
  [90108] = {
    module_page_id = 2079,
    order_in_page = 8,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "At this time, Savin called to check if Kiro would attend the movie festival. You worried that this would let the controversies about the experiment video fester, but Kiro insisted on attending."
  },
  [90109] = {
    module_page_id = 2079,
    order_in_page = 9,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After you left, Kiro used his hacker skills to find that all blood disease patients were Evolvers who suffered from deterioration. He then contacted Lucien to exchange the NW experiment report for information on blood disease."
  },
  [90110] = {
