    module_type = 1,
    module_connect_id = 90111,
    module_to_module_delay = 0.5,
    module_delay = 3,
    module_desc = "After you gave the mechanical box to Zehn for investigation, you hurried to the movie festival. Kiro calmly stood his ground in the face of sharp questions from the reporters about the experiment video."
  },
  [90111] = {
    module_page_id = 2079,
