    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 90113,
    module_to_module_delay = 0.5,
    module_delay = 10,
    module_desc = "After the event, you followed Kiro backstage. He told you someone was taking advantage of [c][f78585]Evol's deterioration[-][/c]. You then immediately thought of the blood disease. You also found out that all Evolver patients could only survive on blood transfusions. When you suggested solutions, Kiro cruelly refuted and claimed that people with power were bound to have more choices. Seeing that you weren't convinced, Kiro decided to use his Evol on you."
  },
  [90113] = {
    module_page_id = 2079,
    order_in_page = 13,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"You will always be influenced by power no matter how determined you are.\"",
    module_card_id = 53611,
