    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You fell asleep after Kiro used his Evol on you, only to wake up and find that he was already gone. When you turned on your phone, you found that there had been a [c][f78585]shooting[-][/c] in the hospital."
  },
  [90115] = {
    module_page_id = 2079,
    order_in_page = 15,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Last night, after a lengthy internal battle, Helios walked into the ward and pulled the trigger at the person on the hospital bed."
  },
  [90116] = {
    module_page_id = 2079,
    order_in_page = 16,
