    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Victor told Poseidon to investigate the sabotaged factories and told Goldman to look for someone."
  },
  [90117] = {
    module_page_id = 2079,
    order_in_page = 17,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The witnesses' testimonies all described Helios. On your way to the hospital, you rang Kiro on the phone. You could sense from his words that he had something to do with the shooting. When you arrived at the hospital, you found that all the victims recovered from [c][f78585]hematopoietic dysfunction[-][/c] but lost their Evols. You then speculated that Kiro was saving their lives this way."
  },
  [90118] = {
    module_page_id = 2079,
    order_in_page = 18,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 90119,
    module_to_module_delay = 0.5,
    module_delay = 3,
    module_desc = "You finally ran into him near the hospital. He didn't deny your speculation, yet he claimed that he was plundering before he rushed off."
  },
  [90119] = {
    module_page_id = 2079,
    order_in_page = 19,
