    module_vol_id = 209,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"I don't regret what I did, neither can I.\"",
    module_card_id = 53610,
    module_CG_zoom = 0.83,
    module_remove = "0,-230",
    module_voice = "voice_123009_70.mp3",
    module_voice_species = 0,
