    module_season_id = 2,
    module_type = 1,
    module_connect_id = 90207,
    module_to_module_delay = 0.5,
    module_delay = 1,
    module_desc = "The world was heading in the wrong direction, but he would set it right."
  },
  [90207] = {
    module_page_id = 2080,
    order_in_page = 7,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"I just don't want some people to get their way so easily.\"",
    role1 = 1125000,
    role2 = 101102,
    role3 = 101201,
    module_role_zoom_rate = 0.5,
    module_remove = "0,-210",
