    order_in_page = 8,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The cruise ship shook. It turned out that the thruster got destroyed. Victor told you the cruise ship was isolated in an [c][f78585]other-dimension[-][/c], and this was already the third sabotage that happened. The person behind the blood virus wanted to use the lives on the ship to force Victor to give away Mr. Chard. At this point, the enemy appeared and threatened Victor's life, yet he faced it with calmness."
  },
  [90209] = {
    module_page_id = 2080,
    order_in_page = 9,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "In the NW laboratory, the equipment showed that the [c][f78585]test subject[-][/c] progress had reached 100%."
  },
  [90210] = {
