    order_in_page = 10,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The ship descended into chaos. Nothing seemed to help the situation. Victor seemed to have expected this and told Mr. Chard the plan. You secretly used the [c][f78585]mechanical box[-][c], hoping to obtain the power to help Victor."
  },
  [90211] = {
    module_page_id = 2080,
    order_in_page = 11,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 90212,
    module_to_module_delay = 0.5,
    module_delay = 11,
    module_desc = "The constant explosions fueled the crowd with panic. A long needle pinned a note onto the wall, claiming that the only way to live was to hand over the person he wanted or to kill Victor. With the blurred concept of time and lack of food, the crowd began to give in and rushed toward Victor in despair to survive. Victor stopped Mr. Chard from revealing his identity and ran toward the corridor with you. When the enemy appeared in the corridor, Victor shoved a note into your hand and shut you outside the door, telling you to get to the room at the end of the corridor."
  },
  [90212] = {
    module_page_id = 2080,
    order_in_page = 12,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"This is something only you can do.\"",
    module_card_id = 51610,
    module_CG_zoom = 0.83,
    module_remove = "0,-218",
    module_voice = "voice_123108_95.mp3",
    module_voice_species = 0,
