    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "In the face of scornful remarks, Victor admitted that he was a lucky man, but it was precisely this luck that kept his head clear. Those who struggled to survive were not failures, which was why he would not point any weapon at them."
  },
  [90214] = {
    module_page_id = 2080,
    order_in_page = 14,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 90215,
    module_to_module_delay = 0.5,
    module_delay = 7,
    module_desc = "Inside the room waited a young man. He said he could send messages across time and space. You needed to send a message to Victor one hour later to tell him to return to the night four days ago to stop the propeller from being damaged to change the past. You were puzzled as to why this was something only you could do, but the young man told you Victor's reply to this question. "
  },
  [90215] = {
    module_page_id = 2080,
