    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After leaving a message, you quickly returned to where you were, but Victor was nowhere to be found. Familiar and unfamiliar images began to flood your mind, while Victor's face gradually faded."
  },
  [90217] = {
    module_page_id = 2080,
    order_in_page = 17,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 90218,
    module_to_module_delay = 0.5,
    module_delay = 7,
    module_desc = "After some time, you opened your eyes again, only to feel that you had forgotten someone very important, and some images from the future had been altered. You followed your intuition to the utility room, then a man covered in blood called out your name with a familiar tone. You didn't know who he was, yet tears began to stream down your face, which the man wiped away."
  },
  [90218] = {
