    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"Why would someone like you be willing to be by my side?\"",
