    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You and Gavin sat on the steps as he talked about Doven and the person whom he never received approval from and would never be able to prove himself."
  },
  [90317] = {
    module_page_id = 2081,
    order_in_page = 17,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 90318,
    module_to_module_delay = 0.5,
    module_delay = 3,
    module_desc = "After taking you home, Gavin weaved through the crowd and stood before Silas at the [c][f78585]celebration party[-][/c]."
  },
  [90318] = {
    module_page_id = 2081,
    order_in_page = 18,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"I'll unearth those secrets, and I'll prevent any potential tragedy it might cause.\"",
    module_card_id = 54610,
