    order_in_page = 19,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After a pause, Silas sneered and told Gavin that he didn't believe [c][f78585]Core[-][/c] had been destroyed. The topic changed when Lucien arrived, saying that the spread of the virus was faster and more malicious than expected."
  },
  [90320] = {
    module_page_id = 2081,
    order_in_page = 20,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The same pain after using the mechanical box washed over you again. In your dream, you saw a girl that turned out to be yourself."
  },
  [90401] = {
    module_page_id = 2082,
    order_in_page = 1,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
