    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 90429,
    module_to_module_delay = 0.5,
    module_delay = 9,
    module_desc = "After confirming that he was fine, you two entered the orphanage, which seemed pretty much the same as seventeen years ago. You then came to a warehouse that was cordoned off and began to flip through the folders on the shelves. You then found a report that recorded many [c][f78585]failed[-][/c] experiments with Lucien's name on it, which was stamped with the words \"damaged good\"! When you were fueled with rage, Lucien came to your side."
  },
  [90429] = {
