    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Despite your heartache, you didn't want to bring up his past traumas. You then found a folder named \"[c][f78585]\"No.0 Experiment Record\"[-][/c] and realized that Core had been inside you all along!"
  },
  [90431] = {
    module_page_id = 2082,
    order_in_page = 31,
    module_unlock_request = 313320,
    module_unlock_request_desc = "Clear stage 33-20 to unlock",
    module_vol_id = 209,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Lucien didn't seem surprised at all. You then remembered the NW experiment you went through and realized that he hid the fact that Core was within you. After all these misunderstandings, you two were finally able to be honest with each other."
  },
  [90432] = {
