  [100102] = {
    module_page_id = 2083,
    order_in_page = 2,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You woke up in pain and found yourself in a [c][f78585]white space[-][/c]. You remember shooting yourself to destroy Core's [c][f78585]barrier[-][/c]. When you tried to escape where you thought to be NW's experiment lab, the space had changed to Twin Leaves Orphanage from 17 years ago, where you encountered [c][f78585]your father[-][/c]."
  },
  [100103] = {
    module_page_id = 2083,
    order_in_page = 3,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "A barrier emerged around your unconscious body. Lucien figured out that the thin film was for [c][f78585]the protection of Core[-][/c] and decided to carry out his plan to wake you up."
  },
  [100104] = {
    module_page_id = 2083,
    order_in_page = 4,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You tried to test your Father, who then explained that his emergence was due to the destruction of the barrier within you and that you were in your [c][f78585]dream[-][/c]. You would wake up when your body had fully absorbed Core, which would be protected by a thin film before then. Your father told you two ways to escape the dream—you could either accept Core or [c][f78585]seal[-][/c] it forever. He also took you to your own [c][f78585]prophetic dream[-][/c] to look at the [c][f78585]future brought about by the awakening[-][/c] of Core."
  },
  [100105] = {
    module_page_id = 2083,
    order_in_page = 5,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Lucien came into your dream and met your Father after their last encounter 17 years ago. Lucien ignored your father's warning and was determined to find you, who was deep in your dream."
  },
  [100106] = {
    module_page_id = 2083,
    order_in_page = 6,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 100107,
    module_to_module_delay = 0.5,
    module_delay = 10,
    module_desc = "You saw that the awakening of Core had brought about [c][f78585]doomsday[-][/c] once more, and Lucien had [c][f78585]sacrificed[-][/c] himself to find out more about Core. This brought you to the brink of breakdown. You felt unsure about the purpose of awakening Core. At this moment, Lucien showed up in your dream. You told him your fear of what the awakening of Core would bring, while he thought you were free to make a decision."
  },
  [100107] = {
    module_page_id = 2083,
    order_in_page = 7,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"It's your choice.\"",
    role1 = 264000,
    role2 = 201105,
    role3 = 201204,
    role5 = 264404,
