  },
  [100108] = {
    module_page_id = 2083,
    order_in_page = 8,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 100109,
    module_to_module_delay = 0.5,
    module_delay = 8,
    module_desc = "You and Lucien came to a house to spend some time thinking, yet you failed to make up your mind. Lucien's strength and open-mindedness made you feel ashamed. He told you to keep thinking and consider every possibility. You became very anxious and decided to go out for a walk. In the face of the confronting noises, you ran into Lucien, hoping he would give you the right answer, while he offered you an invitation."
  },
  [100109] = {
    module_page_id = 2083,
    order_in_page = 9,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"Why don't we go and see something even more special?\"",
    module_card_id = 52630,
    module_CG_zoom = 0.83,
    module_remove = "0,-200",
    module_voice = "voice_123405_70.mp3"
  },
  [100110] = {
