    order_in_page = 10,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Lucien told you that you could [c][f78585]alter your dream[-][/c] and suggested to take a look at the [c][f78585]comet that would destroy the world[-][/c]. You came close to the stunning comet, while Lucien guided you to let out all your burden and stress. You felt that it was your duty to make a decision, while Lucien told you that was not the case because everyone would eventually face death."
  },
  [100111] = {
    module_page_id = 2083,
    order_in_page = 11,
