    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "\"We will eventually become a part of the universe.\""
  },
  [100112] = {
    module_page_id = 2083,
    order_in_page = 12,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 100113,
    module_to_module_delay = 0.5,
    module_delay = 10,
    module_desc = "You could finally look at the situation from a new perspective and feel capable of finding the solution. Lucien then invited you somewhere else. After pushing a door open, you came to the familiar [c][f78585]flower field[-][/c] you saw in the dream on the subway. Yet the place seemed different this time—there was a bellflower field in the snow-capped wheat field. When Lucien asked if you liked this place, you replied with an embrace of gratitude."
  },
  [100113] = {
