    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After you woke up from the experiment table, you told Silas about the approaching doomsday and volunteered to participate in their experiment with [c][f78585]three conditions[-][/c], which Silas eventually agreed to after some negotiation."
  },
  [100116] = {
    module_page_id = 2083,
    order_in_page = 16,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Throughout the excruciating Core experiment, you were glad to have Lucien with you. A few days later, you noticed some [c][f78585]shadows[-][/c] and found that no one was in the lab except Lucien after you stepped across a [c][f78585]thin thread[-][/c]. Lucien told you that Core had caused an unforeseen change in the world—a severe [c][f78585]spatial overlap[-][/c] with [c][f78585]NW at the center[-][/c] had occurred. Lucien believed that you would find the answer, and you walked out of the lab with confidence."
  },
  [100117] = {
