    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Gavin didn't deny it. You explained to him the reasons you volunteered to participate in the experiments. You couldn't convince Gavin to let you work with NW, so he brought you back to his office at the Special Task Force."
  },
  [100224] = {
    module_page_id = 2084,
