    module_to_module_delay = 0.5,
    module_delay = 4,
    module_desc = "Gavin soon gave out orders and made an announcement on the TV about the overlap zone. You felt unfair when you saw the complaints and negative comments about the Special Task Force online, yet Gavin said the Special Task Force was just carrying out their duty."
  },
  [100230] = {
