  [100231] = {
    module_page_id = 2084,
    order_in_page = 15,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You came to the ring in the simulation room as agreed. You told Gavin that you wanted to use NW's technology to research Core. But instead of returning to the lab, you would get them to [c][f78585]develop a cure for the blood disease[-][/c]. Despite his worry and hope to bear everything for you, Gavin eventually decided to believe in you."
  },
  [100232] = {
    module_page_id = 2084,
    order_in_page = 16,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 100233,
    module_to_module_delay = 0.5,
    module_delay = 11,
    module_desc = "You got in touch with Silas, who proposed that NW would develop the cure in two weeks on the condition that they would insert a [c][f78585]tracking chip[-][/c] on you. You agreed to meet on the [c][f78585]glass walkway[-][/c] on the observation tower and have Gavin get the microchip. When Gavin showed up, something about him didn't seem right. You tested him by asking if he would give his life to you, to which Gavin said yes."
  },
  [100233] = {
    module_page_id = 2084,
    order_in_page = 17,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"Take it now if you want.\"",
    module_card_id = 54641,
    module_CG_zoom = 0.83,
    module_remove = "0,-200",
    module_voice = "voice_123509_103.mp3"
  },
  [100234] = {
    module_page_id = 2084,
    order_in_page = 18,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You were certain that this man was not Gavin himself—even if he would give his life to you, he wouldn't do so now before he finished his duties."
  },
  [100235] = {
    module_page_id = 2084,
    order_in_page = 19,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Despite Silas's provocation, you believed that Gavin would eventually show up. At this moment, the real Gavin arrived with the chip he checked through. After inserting the chip into you with his own hands, Gavin escorted you away safely before you went your separate ways."
  },
  [100236] = {
    module_page_id = 2084,
    order_in_page = 20,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "In the middle of the night, you walked into the BS building alone as you remembered the voice you heard in the Black Cabin in the past."
  },
  [100237] = {
    module_page_id = 2084,
    order_in_page = 21,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
