    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Gavin found Helios in Central Hospital to tell him about something. Helios then met up with Victor. The two seemed to be carrying out some plan."
  },
  [100238] = {
