  [100339] = {
    module_page_id = 2085,
    order_in_page = 2,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After sneaking into the BS building, you found the room where the [c][f78585]Black Cabin[-][/c] was. Nonetheless, the door did not open to you without the [c][f78585]key[-][/c]. When you were about to give up, Helios suddenly showed up. At this moment, the door pulled the two of you into the Black Cabin."
  },
  [100340] = {
    module_page_id = 2085,
    order_in_page = 3,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "In the face of Helios's furious questions, you were about to tell him everything, when [c][f78585]the little boy[-][/c] appeared before your eyes and gestured for you to keep quiet. You then heard a familiar voice telling you to leave. A force then kicked both of you out to an alleyway."
  },
  [100341] = {
    module_page_id = 2085,
    order_in_page = 4,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The little boy and the man behind the door chatted in the Black Cabin. It didn't seem to bother them that you might be bringing the world to an end."
  },
  [100342] = {
    module_page_id = 2085,
    order_in_page = 5,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "With the boy's warning in mind, you didn't know how to explain yourself, yet Helios seemed to know you had your reasons. He then asked someone to pick you up before he left to save the blood disease patients."
  },
  [100343] = {
    module_page_id = 2085,
    order_in_page = 6,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 100344,
    module_to_module_delay = 0.5,
    module_delay = 18,
    module_desc = "You got in the car and saw that the city council's [c][f78585]press conference[-][/c] was about to start. You decided to attend with some suspicions in mind. Leto claimed once again that the [c][f78585]blood disease[-][/c] was caused by [c][f78585]Evol deterioration[-][/c]. At this moment, Helios appeared on the screen and claimed to be the culprit of the [c][f78585]virus[-][/c], [c][f78585]overlap zone[-][/c], and [c][f78585]the mechanical boxes[-][/c]."
  },
  [100344] = {
    module_page_id = 2085,
    order_in_page = 7,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"Effective immediately—Let's disappear altogether.\"",
    role1 = 710000,
    role2 = 701101,
    role3 = 301202,
    module_role_zoom_rate = 0.5,
    module_remove = "0,-200",
    module_background_id = 1681,
    module_voice = "voice_123604_131.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [100345] = {
    module_page_id = 2085,
    order_in_page = 8,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The press conference came to an abrupt end. The Special Task Force announced that they would examine all the [c][f78585]water sources[-][/c] and issued a warrant to arrest Helios."
  },
  [100346] = {
    module_page_id = 2085,
    order_in_page = 9,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After receiving a phone call, the chief of the police withdrew the policemen disguised as patients."
  },
  [100347] = {
    module_page_id = 2085,
    order_in_page = 10,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Helios loaded the gun and walked out of a dim room."
  },
  [100348] = {
    module_page_id = 2085,
    order_in_page = 11,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You hurried to the GR headquarters. Through eavesdropping via a bug, you found that GR planned to stop spreading the virus for now and get rid of Helios before more information was leaked. You rushed to the hospital through the overlap zone into the heavily guarded [c][f78585]ICU unit[-][/c]. A gunshot then sounded—Helios barged into the ward you were in and blocked the bullets aimed at the patients. Before the police forced their way in, you got Helios out of the hospital using a [c][f78585]teleport orb[-][/c]."
  },
  [100349] = {
    module_page_id = 2085,
    order_in_page = 12,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 100350,
    module_to_module_delay = 0.5,
    module_delay = 12,
    module_desc = "Helios was furious to see you here. To get you away from him and danger, Helios told you he once extracted [c][f78585]Core[-][/c] from your body to make these bullets that took the patients' Evol away. Despite being shocked, you knew that he wanted you to stay away so that he could face the darkness on his own. You told him you were his accomplice. None of you were willing to compromise, then some headlights from a car shone on you, which turned out to be Helios's man reminding him to run."
  },
  [100350] = {
    module_page_id = 2085,
    order_in_page = 13,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"I owe you one.\"",
    module_card_id = 53651,
    module_CG_zoom = 0.83,
    module_remove = "0,-200",
    module_voice = "voice_123607_125.mp3"
  },
  [100351] = {
    module_page_id = 2085,
    order_in_page = 14,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You faced GR's attack on your escape, then Helios had no choice but to bring you into the [c][f78585]overlap zone[-][/c]. You refused to stay in hiding and fought the enemies with him."
  },
  [100352] = {
    module_page_id = 2085,
    order_in_page = 15,
    module_unlock_request = 313715,
    module_unlock_request_desc = "Clear stage 37-15 to unlock",
    module_vol_id = 210,
    module_season_id = 2,
