    module_connect_id = 100353,
    module_to_module_delay = 0.5,
    module_delay = 6,
    module_desc = "During the fights, you and Helios got onto an abandoned bus to bandage his wounds. But then, an [c][f78585]NW agent[-][/c] showed up and took you away in the name of protecting Core, which Helios accepted to protect you."
  },
  [100353] = {
