  [110212] = {
    module_page_id = 2088,
    order_in_page = 12,
    module_unlock_request = 314021,
    module_unlock_request_desc = "Clear stage 40-21 to unlock",
    module_vol_id = 211,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 110213,
    module_to_module_delay = 0.5,
    module_delay = 10,
    module_desc = "To maximize the power of the [c][f78585]Core[-][/c], you decided to strike a deal with Silas. Bringing you inside the experiment zone, you saw Gavin who managed to escape from the [c][f78585]other dimension[-][/c]. He was surrounded by a gust of wind, as if conducting an experiment. You asked for a chance to speak to Gavin before the experiment began. Gavin shared with you his determination while you told him about your feelings."
  },
  [110213] = {
    module_page_id = 2088,
    order_in_page = 13,
    module_unlock_request = 314021,
    module_unlock_request_desc = "Clear stage 40-21 to unlock",
    module_vol_id = 211,
    module_season_id = 2,
    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"But the thought of you in my heart has dulled the pain.\"",
    role1 = 499000,
    role2 = 403111,
    role3 = 403207,
    role5 = 499401,
    module_role_zoom_rate = 0.5,
    module_remove = "0,-214",
    module_background_id = 1691,
    module_voice = "voice_123941_77.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [110214] = {
    module_page_id = 2088,
    order_in_page = 14,
    module_unlock_request = 314021,
    module_unlock_request_desc = "Clear stage 40-21 to unlock",
    module_vol_id = 211,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The test to amplify the power of the Core was excruciating for you. During the break, Gavin carefully extracted you from the medical pod. He revealed that N.W. had been relentlessly pursuing a mysterious \"[c][f78585]gate[-][/c],\" and was currently trying to pull it into Loveland City from an alternate dimension. Silas had somehow correctly deduced that you were in a time loop and wanted to see the experiments on the Core carried to the end. However, Gavin intervened and put a stop to it."
  },
  [110215] = {
    module_page_id = 2088,
    order_in_page = 15,
    module_unlock_request = 314021,
    module_unlock_request_desc = "Clear stage 40-21 to unlock",
    module_vol_id = 211,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 110216,
    module_to_module_delay = 0.5,
    module_delay = 11,
    module_desc = "However, you still managed to convince Gavin to continue the experiment. After countless loops, you learned many new things about the Core, and Gavin managed to pull the gate out from the other dimension. As you did, you began to get a strange feeling that the gate was giving you some sort of [c][f78585]answer[-][/c]. Arriving at the conclusion, you and Gavin escaped from the compound, and the door, losing its power source, dissolved away. As you tried to escape, N.W. was one step faster and managed to take you away. However, Gavin came to the rescue and put an end to N.W.'s scheme."
  },
  [110216] = {
    module_page_id = 2088,
    order_in_page = 16,
    module_unlock_request = 314021,
    module_unlock_request_desc = "Clear stage 40-21 to unlock",
    module_vol_id = 211,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"Only my decisions can guide my actions.\"",
    module_card_id = 54670,
    module_CG_zoom = 0.83,
    module_remove = "0,-200",
    module_voice = "voice_123943_53.mp3"
  },
  [110217] = {
    module_page_id = 2088,
    order_in_page = 17,
    module_unlock_request = 314021,
    module_unlock_request_desc = "Clear stage 40-21 to unlock",
    module_vol_id = 211,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Making sure you were safe, Gavin told you about the vague feelings that had been circling in his mind. He told you that despite he would not remember anything when the next loop began, he would be reunited with you in the future when the [c][f78585]truth[-][/c] was revealed."
  },
  [110218] = {
    module_page_id = 2088,
