    module_desc = "Goodbye, Gavin."
  },
  [110219] = {
    module_page_id = 2088,
    order_in_page = 19,
    module_unlock_request = 314021,
    module_unlock_request_desc = "Clear stage 40-21 to unlock",
    module_vol_id = 211,
    module_season_id = 2,
