    module_desc = "[c][f78585][Evol Energy][-][/c] "
  },
  [110220] = {
    module_page_id = 2088,
    order_in_page = 20,
    module_unlock_request = 314021,
    module_unlock_request_desc = "Clear stage 40-21 to unlock",
    module_vol_id = 211,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "According to π, you'll also need a large amount of Evol energy. Remembering your time from the Game of Hunters, you returned to the lighthouse in search of Joker, only to find that Helios was also here. Appearing to have struck a deal with Joker, Helios informed you that he has received a signal inside the lighthouse from the last Key, and that he also found the lighthouse's central network."
  },
  [110221] = {
    module_page_id = 2088,
    order_in_page = 21,
    module_unlock_request = 314021,
    module_unlock_request_desc = "Clear stage 40-21 to unlock",
    module_vol_id = 211,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You called out to π, who admitted that the reason Evol energy could open the lighthouses was because they broke one of the paths from the [c][f78585]cone model[-][/c]. Not expecting the [c][f78585]Game of Hunters[-][/c] turned out to be an integral part of the plan, the accumulated Evol Energy was stored inside each lighthouse. If you were to harness those powers, one lighthouse must serve as the [c][f78585]beacon[-][/c] to converge them together."
  },
  [110222] = {
    module_page_id = 2088,
    order_in_page = 22,
    module_unlock_request = 314021,
    module_unlock_request_desc = "Clear stage 40-21 to unlock",
    module_vol_id = 211,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 110223,
    module_to_module_delay = 0.5,
    module_delay = 7,
    module_desc = "Helios informed you that he could use the lighthouse's central network to combine the energy and become the beacon. As you went ahead with the plan, he expressed a desire to talk to you in private. Returning to Loveland City, you ran into an ad that Helios starred in during the last apocalypse. He told you that he had long had this vague feeling about the truth."
  },
  [110223] = {
