    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [130143] = {
    module_page_id = 2096,
    order_in_page = 1,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 0,
    module_to_module_delay = 0.5,
    module_img = 4793,
    module_page_bgm = "1007_Kingdom_of_This_World",
    module_name = "Tide of Darkness"
  },
  [130144] = {
    module_page_id = 2096,
    order_in_page = 2,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "As the black hole vanished, the ship continued to explode, trapping you inside the cabin. In the nick of time, Kiro arrived to rescue you. A young man addressed Kiro as [c][f78585]Boss[-][/c] and reported finding fragments of a B.S. bomb at the scene. Kiro confessed to you that he had become the new leader of B.S., but unfortunately, this coincided with [c][f78585]G.R.'s[-][/c] aggressive attacks on B.S. You asked him what he intended to do as the leader of [c][f78585]B.S.[-][/c], to which Kiro replied that his plans hadn't changed, but there were many other ways to achieve his goals."
  },
  [130145] = {
    module_page_id = 2096,
    order_in_page = 3,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Upon arriving at B.S., Kiro put a mask on you and invited you to join the [c][f78585]council of the Twelve Deities[-][/c]. Just before the meeting started, Hades arrived late to the meeting. Kiro revealed that G.R. had tried to destroy the Core and frame B.S. for bombing the ship, sparking a discussion among the Deities. Minos suggested that the Core should be reclaimed by B.S., but Kiro asserted his authority to decide how to use the [c][f78585]Core's[-][/c] power. Hermes, who had been silent, scoffed at Kiro and prepared to leave. Kiro had already found out about Hermes' secret dealings with Poseidon's mechanical box factory. Enraged, Hermes attacked Kiro but was subdued."
  },
  [130146] = {
    module_page_id = 2096,
    order_in_page = 4,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "A group of people in black surrounded the meeting room, and Kiro declared that no one could leave until the meeting was over. Kiro received word that G.R. was set to conduct a drug trade at the seaside port within an hour. Kiro sent [c][f78585]Hades[-][/c] to intercept the transaction, which was successfully thwarted. Before adjourning, Kiro pressured the Deities to commit to opposing G.R. After the meeting, you expressed concern about Hades, but Kiro told you that this was all bait, as G.R.'s main goal tonight was a shipment of bullets designed to counter Evolvers. Sensing that G.R. was on a destructive path, you decided to help Kiro fight against G.R. and told him to investigate on [c][f78585]Leto[-][/c]. Kiro also mentioned that he would protect you for the coming period."
  },
  [130147] = {
    module_page_id = 2096,
    order_in_page = 5,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The next day, news outlets reported finding bomb fragments with the B.S. emblem at the bomb site, putting B.S. at the center of public attention, with many fearing the organization's potential threat to public safety. The rapid spread of public opinion made you suspect manipulation behind the scenes, prompting you to ask Zehn to investigate. Among the trending news, you also saw that a studio called Infinite was developing a virtual reality game. Zehn's investigation revealed that the company being the smear campaign was backed by G.R. You immediately sent the information to Kiro while also reminding him not to stay up too late."
  },
  [130148] = {
    module_page_id = 2096,
    order_in_page = 6,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 130149,
    module_to_module_delay = 0.5,
    module_delay = 4,
    module_desc = "Kiro, in his car, looked at the message you sent him."
  },
  [130149] = {
    module_page_id = 2096,
    order_in_page = 7,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"It's magic time.\"",
    module_card_id = 53730,
    module_CG_zoom = 0.83,
    module_remove = "0,-160",
    module_voice = "voice_124705_39.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [130150] = {
    module_page_id = 2096,
    order_in_page = 8,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Kiro's subordinate Keegan contacted him, having located G.R. members hiding nearby. Kiro took one last look at your window and resolutely left alone."
  },
  [130151] = {
    module_page_id = 2096,
    order_in_page = 9,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "As you lay restless on a rainy night, he called you, vividly describing the rainy scenery, but you yearned to see him, hoping that Mr. Little Bear could cast a sleep spell on you. He gladly agreed but wanted you to help him. He said the spell would take effect if you counted to [c][f78585]ninety-nine little bears[-][/c]. When you reached ninety-nine, he appeared, promising to bring you the most beautiful dreams. The next day, you woke to find Kiro investigating Leto, but to no avail. Then, a trending news item listed all of G.R.'s crimes to date, including your name as part of G.R."
  },
  [130152] = {
    module_page_id = 2096,
    order_in_page = 10,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The people on the list faced widespread backlash online, and Kiro discovered that the list had been leaked by someone within B.S. He took extensive measures to remove the malicious websites and comments, stating that anything concerning you was his responsibility. When you arrived at the office, the internet backlash had grown, and you received a barrage of abusive phone calls. After picking up the third call, you heard Kiro's urgent voice and finally broke down crying. He asked if you wanted to run away with him."
  },
  [130153] = {
    module_page_id = 2096,
    order_in_page = 11,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 130154,
    module_to_module_delay = 0.5,
    module_delay = 11,
    module_desc = "To avoid reporters and paparazzi near the office, he picked you up as Helios. In the car, he offered you candies to lift your spirits. He took you on a cable car ride. With the view of the expansive skies and clouds, you felt a momentary escape from the abuse and stress. It was then that Helios noticed a B.S. [c][f78585]drone[-][/c] following you, which he promptly shot down. His warning made you aware of the potential [c][f78585]dangers[-][/c] around you."
  },
  [130154] = {
    module_page_id = 2096,
    order_in_page = 12,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"What a nuisance. They really need to find something better to do.\"",
    module_card_id = 53731,
    module_CG_zoom = 0.83,
    module_remove = "0,-200",
    module_voice = "voice_124707_54.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [130155] = {
    module_page_id = 2096,
    order_in_page = 13,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The next day, the walls outside your office were vandalized with profanities and malicious words. While everyone was at a loss, Kiro arrived carrying a bucket of paint. He [c][f78585]covered[-][/c] the hateful words with various paintings, and many of your co-workers joined in. After finishing, you returned to the office. In the elevator, Kiro sensed something was off with Savin and successfully deduced that he was [c][f78585]Anole[-][/c] in disguise. Following a chase, you subdued him. Kiro then asked if you were willing to watch a show unfold."
  },
  [130156] = {
    module_page_id = 2096,
    order_in_page = 14,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You assumed someone else's identity and attended a secret meeting organized by Hades. Before the meeting started, you passed a USB drive to one of the attendees as Kiro requested. Someone expressed impatience with Anole's late arrival, and then Kiro appeared on a large screen, announcing that no one else would be arriving. Suddenly men in black entered to control the scene. Kiro then held them accountable for leaking the G.R. list and putting the Core in danger."
  },
  [130157] = {
    module_page_id = 2096,
    order_in_page = 15,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "A G.R. agent phoned Leto, pleading for aid and reporting the deaths of six members within a week. Leto, however, turned a cold blind eye to his desperate plea."
  },
  [130158] = {
    module_page_id = 2096,
    order_in_page = 16,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Kiro warned the attendees before severing the connection, leaving an enraged Hades to clash with the men in black. It turned out Kiro had been disguised among them all along. He used the chaos to lead you away, revealing that the video call had been prerecorded. On the way home, he told you that the G.R. list leak was just a small obstacle on your journey and that there would be many more challenges ahead. You confessed that you had been initially scared, but someone had given you a [c][f78585]garden[-][/c], a symbol of hope that no matter how long or bumpy the road, you would eventually catch up with him. You both [c][f78585]vowed[-][/c] to always strive toward your goals."
  },
  [130159] = {
    module_page_id = 2097,
    order_in_page = 1,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 0,
    module_to_module_delay = 0.5,
    module_img = 4796,
    module_page_bgm = "1007_Kingdom_of_This_World",
    module_name = "Behind the Abyss"
  },
  [130160] = {
    module_page_id = 2097,
    order_in_page = 2,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Kiro called Lucien to inquire about the [c][f78585]missing B.S. Deities[-][/c] and proposed to trade it with a piece of information."
  },
  [130161] = {
    module_page_id = 2097,
    order_in_page = 3,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After B.S. launched a full-scale war against G.R., you were finally free from the negative public opinion, but this also meant dealing with a complex PR campaign. As you were preparing to attend the filming of a news program at the [c][f78585]TV tower[-][/c], you noticed the Special Task Force was also on the list. Wondering when Gavin might return, he suddenly appeared in the corridor, dressed in formal attire. He informed you that he would be representing the task force on camera. On the way to the TV tower, Gavin discussed the ongoing investigation into the mysterious person at the shooting range and confirmed his connections with G.R."
  },
  [130162] = {
    module_page_id = 2097,
    order_in_page = 4,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Upon arriving at the venue, Gavin informed you that he was responsible for perimeter security and provided you with an earpiece for communication. You tested the earpiece before entering the [c][f78585]VIP elevator[-][/c], where you encountered several businessmen engaged in a lively discussion about Evolvers. However, the elevator soon malfunctioned, and the doors refused to open. You contacted Gavin via the earpiece to report the issue, but when you pressed the emergency button, a man's voice came through, threatening vengeance on those supporting Evolvers and promoting G.R.'s ideology. He then cut off the communication, and the elevator abruptly started accelerating."
  },
  [130163] = {
    module_page_id = 2097,
    order_in_page = 5,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 130164,
    module_to_module_delay = 0.5,
    module_delay = 10,
    module_desc = "As the elevator ascended uncontrollably, panic erupted among the passengers. You remained calm and directed everyone to try and brace themselves. Meanwhile, Gavin informed you that the elevator couldn't be stopped remotely. His plan was to cut the elevator cable and use the wind to cushion its fall. Despite your concerns, you trusted Gavin's judgment. When the cable was finally cut, Gavin skillfully used the wind to slow the elevator's descent, successfully bringing it to a safe stop."
  },
  [130164] = {
    module_page_id = 2097,
    order_in_page = 6,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"I've got you.\"",
    module_card_id = 54720,
    module_CG_zoom = 0.83,
    module_remove = "0,-200",
    module_voice = "voice_124803_69.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [130165] = {
    module_page_id = 2097,
    order_in_page = 7,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After the ordeal, you and Gavin sat together. You thanked him for his courage and learned about the concerns he had before making the decision to cut the cable."
  },
  [130166] = {
    module_page_id = 2097,
    order_in_page = 8,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Later, you went to the Special Task Force to assist with the investigation. You discovered that the elevator saboteur was motivated by revenge after embracing G.R.'s ideology, though he wasn't an actual G.R. member. This deepened your concerns about the existing tensions between ordinary people and Evolvers. During the investigation, Tang entered and discussed potential suspects with Gavin. He revealed that Gavin had captured a wealthy woman named [c][f78585]Lily White[-][/c], who was planning to attend a [c][f78585]special auction[-][/c] organized by the remnants of G.R., who also wanted to gain her financial support. Gavin was preparing to disguise himself as a jewelry merchant to connect with the person distributing G.R.'s tickets, but he hadn't yet found someone to impersonate Lily White. Eager to help Gavin dismantle G.R. entirely, you volunteered for the role."
  },
  [130167] = {
    module_page_id = 2097,
    order_in_page = 9,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The next day, you and Gavin prepared yourselves at a mansion, awaiting the arrival of G.R.'s representative with the tickets. The representative arrived on time, and since Lily White had never publicly revealed her face, you managed to convince the G.R. agent with your replies, easing their suspicions and securing the tickets. However, when you and Gavin attempted to glean more details about the auction, the agent remained tight-lipped, heightening your concerns about what the [c][f78585]auctioned items[-][/c] might be."
  },
  [130168] = {
    module_page_id = 2097,
    order_in_page = 10,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "On the day of the auction, Gavin gave you part of the recording equipment and instructed you on how to defeat the security measures. The small hitches along the way forced Gavin to hand off the remaining equipment to you, but you both successfully entered the venue with it in tow."
  },
  [130169] = {
    module_page_id = 2097,
    order_in_page = 11,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Following Gavin backstage, you made a horrifying discovery: the auction items were captured Evolvers. Behind the backstage, you found someone in need of rescue and successfully freed him with some inside help. To ensure the success of the operation, Gavin decided to take the rescued man's place and go onstage as an auction item himself. After planning, you handcuffed Gavin and returned to the auction to help him buy time. As the performance concluded and the lead performer transformed into the auctioneer, Evolvers were brought up for sale one by one to an eager audience. When it was Gavin's turn, you received his cue to delay for ten minutes, prompting you to join the bidding. After a fierce auction, you won Gavin and used the pretext of inspecting the merchandise to speak to him. Just as you were about to take him away, the auctioneer demanded to verify your funds."
  },
  [130170] = {
    module_page_id = 2097,
    order_in_page = 12,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Struggling to maintain your composure, you invited the auctioneer to proceed with the verification, hoping to buy more time. However, he saw through your ruse and fired a gunshot, exposing your disguise and causing a commotion. Gavin then revealed his own identity to protect you and managed to subdue the auctioneer. With the help of the Special Task Force, the remaining people in the hall were quickly subdued. As Gavin prepared to pursue those who had fled earlier, they were brought back in by Silas, who arrived leading a detachment of N.W. agents. Gavin confronted Silas, who seemed to be searching for someone. Just then, the mysterious figure who had previously attacked Gavin at the shooting range made a sudden escape. After ensuring no G.R. members were left, Gavin declared the operation over."
  },
  [130171] = {
    module_page_id = 2097,
    order_in_page = 13,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 130172,
    module_to_module_delay = 0.5,
    module_delay = 9,
    module_desc = "Afterward, you and Gavin went to the rooftop to watch the sunrise as you two enjoyed a peaceful interlude after the intense events. Reflecting on all that had transpired, you voiced your concerns about the uncertain path ahead. In turn, [c][f78585]Gavin shared his own dream from when he first joined the Special Task Force, assuring you that there were many others in the world who shared your hope for a better future[-][/c]. His words left you feeling greatly inspired."
  },
  [130172] = {
    module_page_id = 2097,
    order_in_page = 14,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"Consider it a reward for a good Samaritan.\"",
    module_card_id = 54721,
    module_CG_zoom = 0.83,
    module_remove = "0,-200",
    module_voice = "voice_124810_13.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [130173] = {
    module_page_id = 2097,
    order_in_page = 15,
    module_unlock_request = 314815,
    module_unlock_request_desc = "Clear stage 48-15 to unlock",
    module_vol_id = 213,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Inside your office, a sentence suddenly appeared on your computer before dissolving into a jumble of codes."
  },
  [140101] = {
    module_page_id = 2098,
    order_in_page = 1,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 0,
    module_to_module_delay = 0.5,
    module_img = 4750,
    module_page_bgm = "1011_Absurd_Paradise",
    module_name = "End of the Journey"
  },
  [140102] = {
    module_page_id = 2098,
    order_in_page = 2,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After the raid on G.R.'s underground auction, Gavin warned you of a new threat brewing in Loveland City. But until it fully emerged, all you could do was prepare to weather the coming storm. With IT's help, you managed to repair your virus-stricken computer. While sifting through emails, you stumbled upon news about [c][f78585]Jason's[-][/c] contract termination as Victor's face flashed in your mind. But before you could dwell on it, Goldman called, summoning you to LFG. Gathering your materials, you headed out."
  },
  [140103] = {
    module_page_id = 2098,
    order_in_page = 3,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Once at LFG, you found a secluded corner in the staff lounge to review the meeting notes. Unexpectedly, Victor appeared. In response to your questions, he revealed that Zero had taken him to a place called the [c][f78585]Spacetime Bureau[-][/c], though nothing significant had happened there. Victor then asked about the meeting report, offering insights on LFG's situation and suggesting a focus beyond mere business strategies. When the meeting commenced, LFG's actual decisions aligned with his suggestions, deepening your curiosity about the man before you."
  },
  [140104] = {
    module_page_id = 2098,
    order_in_page = 4,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 140105,
    module_to_module_delay = 0.5,
    module_delay = 13,
    module_desc = "After resolving LFG's immediate issues, you decided to treat Victor to your favorite restaurant, Souvenir. Though temporarily closed, Mr. Mills still let you in. You offered to cook, but midway through, you noticed Victor's strange familiarity with French cuisine as he prepared a simplified version of Beef Bourguignon. The taste hit your tongue with a surge of \"nostalgia.\" As you savored the moment, Victor asked why you were so determined to help him. Without hesitation, you laid your thoughts bare, and Victor's expression softened, as if a weight had lifted."
  },
  [140105] = {
    module_page_id = 2098,
    order_in_page = 5,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"As for who I am... I believe time will tell.\"",
    role1 = 124000,
    role2 = 101103,
    role3 = 101202,
    module_role_zoom_rate = 0.5,
    module_remove = "0,-210",
    module_background_id = 1291,
    module_voice = "voice_124904_100.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [140106] = {
    module_page_id = 2098,
    order_in_page = 6,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You allowed Victor to stay overnight at Souvenir. The next morning, you were greeted by a freshly baked caramel pudding. The familiar sweetness seemed to thaw something long frozen inside you, yet it still felt incomplete. You continued your stroll of Loveland City with Victor, wandering from Floral Road to Sunshine Alley, and finally stopping at the Central Park. As you casually asked about LFG's theoretical collapse, Victor's rational analysis cast a somber pall over your thoughts, bringing to your mind his lost memories. Continuing through the park, a seemingly ordinary tree suddenly stood out in your view. Approaching it triggered a cascade of memories, awakening the Core within you and transporting you both to the day of the Lantern Show in the past."
  },
  [140107] = {
    module_page_id = 2098,
    order_in_page = 7,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "When Victor regained consciousness, you were gone. He tried to navigate the bustling crowd in search of you but was pushed back repeatedly. Determined, he pressed on through the throng."
  },
  [140108] = {
    module_page_id = 2098,
    order_in_page = 8,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 140109,
    module_to_module_delay = 0.5,
    module_delay = 18,
    module_desc = "When you opened your eyes, everything around you was an exact recreation of the Lantern Show from your memories. You searched desperately for Victor but were met instead by an unseen force nudging you forward, back toward the familiar ice cream stand. You sensed that something was guiding you along your original path, but you defied it, intent on finding Victor and leaving with him. Pushing through the crowd, you reached a small lantern stall, where the vendor suggested you set loose a lantern to find the person you were looking for. You noticed many discarded lanterns nearby. As you picked one up, the dust-covered words etched upon it gripped your heart. With a rush of clarity, you remembered everything about Victor. You lit the lantern, hoping it would guide him to you. At last, when you released the lantern representing Victor's old wish, he emerged from the glow."
  },
  [140109] = {
    module_page_id = 2098,
    order_in_page = 9,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"What matters the most is you.\"",
    role1 = 129000,
    role2 = 101104,
    role3 = 101202,
    module_role_zoom_rate = 0.5,
    module_remove = "0,-210",
    module_background_id = 8042,
    module_voice = "voice_124906_37.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [140110] = {
    module_page_id = 2098,
    order_in_page = 10,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Victor had returned, with his memories fully intact. Together, you prepared to write a new [c][f78585]wish[-][/c] on a blank lantern. As it soared skyward, your powers brought you both back to Loveland City."
  },
  [140111] = {
    module_page_id = 2098,
    order_in_page = 11,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "A young boy watched a tablet screen, where news of LFG's CEO missing after a car accident played in prominence. He warned you of the [c][f78585]consequences of altering destiny[-][/c]."
  },
  [140112] = {
    module_page_id = 2098,
    order_in_page = 12,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 140113,
    module_to_module_delay = 0.5,
    module_delay = 9,
    module_desc = "Back in reality, a nurse's voice woke you, and you found yourself in a hospital room. From the nurse's brief explanation, you learned that Victor had been brought here by you after an [c][f78585]car accident[-][/c]. Through the glass, you saw Victor lying on the hospital bed. Your heart twisted with pain, but all you could do was wait until he finally awoke."
  },
  [140113] = {
    module_page_id = 2098,
    order_in_page = 13,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"You... dummy...\"",
    module_card_id = 51770,
    module_CG_zoom = 0.83,
    module_remove = "0,-200",
    module_voice = "voice_124907_91.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [140114] = {
    module_page_id = 2098,
    order_in_page = 14,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Victor was slowly recovering, but those around him didn't immediately remember him as LFG's CEO. While discussing the recent event, Goldman suddenly called, explaining that LFG was caught in a media storm and that he had suddenly remembered who Victor was. With Goldman's help, you and Victor began strategizing a response to LFG's crisis. The initial white paper had evolved into massive commercial disputes between LFG and its subsidiaries, sparking protests. Victor explained that he needed full acknowledgment of his existence before he could officially return. You decided to leverage the media to help the public remember him quickly."
  },
  [140115] = {
    module_page_id = 2098,
    order_in_page = 15,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 140116,
    module_to_module_delay = 0.5,
    module_delay = 10,
    module_desc = "As preparations advanced, Victor took you to his [c][f78585]vault[-][/c], where his amassed fortune lay. By the time of the meeting, public opinion had shifted in your favor, and Victor was gradually regaining control within the company. On the day of the meeting, you were both ready for what was coming."
  },
  [140116] = {
    module_page_id = 2098,
    order_in_page = 16,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"LFG shall not fall under my watch.\"",
    module_card_id = 51771,
    module_CG_zoom = 0.83,
    module_remove = "0,-200",
    module_voice = "voice_124909_74.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [140117] = {
    module_page_id = 2098,
    order_in_page = 17,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "At the meeting, Gordon Kwan aggressively confronted Victor, exploiting LFG's vulnerabilities and demanding early disclosure of its financial reports. You realized that Gordon's true goal was to bring down LFG and exploit its downfall for his own gains. Yet Victor navigated the confrontation with calculated precision, ultimately intimidating the other partners and resolving the crisis with his sheer presence. With LFG stabilized, Victor prepared to depart for abroad. You promised to handle LFG's affairs until his return."
  },
  [140118] = {
    module_page_id = 2098,
    order_in_page = 18,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "As Victor waited in the car, Zero arrived as expected, demanding Victor pay [c][f78585]the price of the deal[-][/c]. But Victor turned the tables, questioning whether [c][f78585]time was truly immutable[-][/c]."
  },
  [140201] = {
    module_page_id = 2099,
    order_in_page = 1,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 0,
    module_to_module_delay = 0.5,
    module_img = 4750,
    module_page_bgm = "1011_Absurd_Paradise",
    module_name = "Beneath the Cacophony"
  },
  [140202] = {
    module_page_id = 2099,
    order_in_page = 2,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Inside the Task Force office, Gavin was in the middle of a call with the City Council, discussing the unfolding case. When he learned that they had no intention of disclosing the truth, he let out a cold laugh before hanging up."
  },
  [140203] = {
    module_page_id = 2099,
    order_in_page = 3,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 140204,
    module_to_module_delay = 0.5,
    module_delay = 3,
    module_desc = "Late night back home, after handling the media coverage of the LFG crisis, you casually browsed through social news. One report stood out—eyewitnesses claimed to have seen [c][f78585]sightings of ghosts[-][/c]. Your curiosity was piqued, prompting a decision to contact Gavin later. But suddenly, his voice broke the silence."
  },
  [140204] = {
    module_page_id = 2099,
    order_in_page = 4,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"But I don't want to wait.\"",
    role1 = 428000,
    role2 = 403111,
    role3 = 403203,
    role5 = 428401,
    module_role_zoom_rate = 0.5,
    module_remove = "0,-214",
    module_background_id = 1874,
    module_voice = "voice_125001_36.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [140205] = {
    module_page_id = 2099,
    order_in_page = 5,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The weariness in Gavin's expression tugged at your heart. He explained that the City Council was adopting a stalling tactic. They had hoped to divert the public's attention elsewhere, which is why the recent \"ghost sightings\" have been all over the news. In reality, the phenomenon was merely caused by \"[c][f78585]pseudo-spatial rifts[-][/c].\" When you suggested documenting the rift's occurrence, Gavin proposed taking you to the scene so you could \"see it with your own eyes.\" As you captured the rift through the lens, a fleeting surge of power rippled through the air."
  },
  [140206] = {
    module_page_id = 2099,
    order_in_page = 6,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 140207,
    module_to_module_delay = 0.5,
    module_delay = 10,
    module_desc = "After leaving the site, Gavin took you to a residential house. When the door opened, you were surprised to see [c][f78585]Officer Yim[-][/c], whom you hadn't seen for a while. He looked more frail than before. Concerned, you asked about his health, and he assured you it was just a lingering cold before shifting the topic to the case. That's when you learned that the [c][f78585]Fulcrum Foundation[-][/c] had been colluding with several City Council officials, funneling charity funds into criminal ventures. As you left Officer Yim's home, you resolved to support Gavin by rallying public attention. Gavin suggested that the Task Force participate in an exclusive interview to bring the truth back into focus."
  },
  [140207] = {
    module_page_id = 2099,
    order_in_page = 7,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"The target's right in front of us. I'm going to give it everything I've got.\"",
    role1 = 4154000,
    role2 = 402110,
    role3 = 402202,
    role5 = 4154401,
    module_role_zoom_rate = 0.5,
    module_remove = "0,-214",
    module_background_id = 1111,
    module_voice = "voice_125003_84.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [140208] = {
    module_page_id = 2099,
    order_in_page = 8,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Back at the office, you reached out to various media outlets, but none accepted your invitation under the mounting pressure. Frustrated, you went outside to clear your head, only to encounter Officer Yim feeding a stray dog nearby. With a calm voice, he analyzed the situation for you. You were reminded of his relentless pursuit of truth after the [c][f78585]New Year Coup[-][/c] and felt your determination greatly rekindled."
  },
  [140209] = {
    module_page_id = 2099,
    order_in_page = 9,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "On the day of the interview, you led the crew to the task force's headquarters. With deft coordination, you and Gavin steered the conversation toward the [c][f78585]missing people[-][/c], mentioning an upcoming City Council press conference that would clarify the situation. When asked whether the current public's unwillingness to act would affect the Task Force, Gavin responded firmly: His pledge to truth and justice will never waver."
  },
  [140210] = {
    module_page_id = 2099,
    order_in_page = 10,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "In the N.W. observation room, Lucien's gaze lingered on the shifting [c][f78585]rift energy markers[-][/c] on the map, his eyes narrowing at a newly marked location—the Special Task Force headquarters."
  },
  [140211] = {
    module_page_id = 2099,
    order_in_page = 11,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The interview sparked a strong reaction, with skyrocketing views drawing media outlets eager to secure broadcast rights. During a video conference, you declared that $c was willing to hand out broadcasting rights for free, appealing to each company about the true responsibility of every journalist."
  },
  [140212] = {
    module_page_id = 2099,
    order_in_page = 12,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "In an alley near the parking lot, Officer Yim intercepted a person sent to oversee the foundation's transaction. During the ensuing struggle, he suddenly turned pale, and the suspect tried to flee but was quickly subdued by Gavin. Relief was short-lived as Gavin saw Officer Yim collapse heavily to the ground."
  },
  [140213] = {
    module_page_id = 2099,
    order_in_page = 13,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "As you wrapped up the video conference, an unexpected call came from the City Council. The caller, identifying himself as a representative from the Public Relations Department, requested a face-to-face meeting about the Special Task Force interview. You reached out to Gavin first but sensed something was wrong in his voice. You rushed to the Central Hospital, where you found Gavin's tense figure outside the emergency room. It was then you learned that Officer Yim had been suffering from a [c][f78585]Evol Deterioration Disorder[-][/c], but still choosing to devote his final days to the task force's cause."
  },
  [140214] = {
    module_page_id = 2099,
    order_in_page = 14,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The emergency room doors swung open, and the doctor regretfully informed you that further treatment would only prolong Officer Yim's suffering. You and Gavin rushed into the hospital room, where Officer Yim, hearing that the mission was a success, finally closed his eyes. Tears blurred your vision as the nurse handed Gavin a [c][f78585]police badge[-][/c]—Officer Yim's last possession."
  },
  [140215] = {
    module_page_id = 2099,
    order_in_page = 15,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 140216,
    module_to_module_delay = 0.5,
    module_delay = 3,
    module_desc = "A few days later, you and Gavin stood before Officer Yim's grave, flowers in hand. The sprawling cemetery was cloaked in a heavy silence as Gavin stood before the tombstone and offered a solemn salute."
  },
  [140216] = {
    module_page_id = 2099,
    order_in_page = 16,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"You're right. Their hope lives on in me. I won't let them down.\"",
    module_card_id = 54761,
    module_CG_zoom = 0.83,
    module_remove = "0,-200",
    module_voice = "voice_125007_44.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [140217] = {
    module_page_id = 2099,
    order_in_page = 17,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Moved by Gavin's unwavering resolve, you felt a bitter ache in your chest. Sensing your turmoil, Gavin gently took your hand. Suddenly, an unfamiliar voice pierced the quiet—it was the City Council's representative, who had somehow tracked you down here."
  },
  [140218] = {
    module_page_id = 2099,
    order_in_page = 18,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You tried to hide your anger as you confronted the representative, who demanded you come to the City Council immediately. In a flash, Gavin stepped forward, forcefully pulling the intruder away from Officer Yim's grave and coercing him to work together. As it turned out, Gavin had already investigated the representative's background. After a tense negotiation, the representative agreed to hold a [c][f78585]press conference[-][/c] in exchange for [c][f78585]some time[-][/c] to arrange for replacements in the City Council's current roster. Once the representative left, you and Gavin discovered a hidden [c][f78585]data port[-][/c] inside Officer Yim's police badge."
  },
  [140219] = {
    module_page_id = 2099,
    order_in_page = 19,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The press conference proceeded as scheduled a few days later. However, the City Council's spokesperson insisted on a uniform narrative, glossing over key details of the case. Despite your objections, the spokesperson remained unmoved, reminding Gavin to stick to the script. Gavin met your eyes from across the room, then abruptly folded his [c][f78585]script[-][/c] and spoke directly to the camera, insisting that the truth must be made public."
  },
  [140220] = {
    module_page_id = 2099,
    order_in_page = 20,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 140221,
    module_to_module_delay = 0.5,
    module_delay = 14,
    module_desc = "The room erupted in chaos. While the City Council representative from earlier remained silent, some reporters began to question Gavin's statements, but he calmly refuted each point, presenting the evidence of the investigation and arrests, assuring that City Hall was addressing the affected sectors. Amid the uproar, you stood resolute, promising to deliver the absolute truth alongside the Special Task Force. Slowly, one by one, representatives from [c][f78585]media companies[-][/c] began to raise their hands, making the same commitment. Gavin's voice resonated through the room, vowing to pursue relentlessly until justice has been served."
  },
  [140221] = {
    module_page_id = 2099,
    order_in_page = 21,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"We're coming for you.\"",
    module_card_id = 54760,
    module_CG_zoom = 0.83,
    module_remove = "0,-200",
    module_voice = "voice_125010_61.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [140222] = {
    module_page_id = 2099,
    order_in_page = 22,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "After the press conference, you began arranging follow-up coverage and learned of a new game, called [c][f78585]Odyssey[-][/c], currently in the spotlight. With all preparations complete, you smiled at Gavin, telling him you were ready to tackle the next challenge. Gavin met your gaze with a promise: he would be waiting for you to collect your \"reward\" whenever you were ready."
  },
  [140301] = {
    module_page_id = 2100,
    order_in_page = 1,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 0,
    module_to_module_delay = 0.5,
    module_img = 4750,
    module_page_bgm = "1011_Absurd_Paradise",
    module_name = "Heart and Mind"
  },
  [140302] = {
    module_page_id = 2100,
    order_in_page = 2,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Infinite's new game, [c][f78585]Odyssey[-][/c], had taken the world by storm as it continued to trend for days. An invitation to collaborate on its promotional campaign landed in your inbox, signaling the start of a major new project. But when you returned home after a long day, a strange delivery awaited you—a package dated ten days into the future, alongside an injured \"Lucien\" at your doorstep. Yet, like phantoms, both vanished before you could even touch them. Just then, the real Lucien arrived. Calmed, you wondered aloud if the vision was the result of a [c][f78585]spatial rift[-][/c]. Lucien noted that many organizations are currently investigating these rifts. The rift had likely been a projection of the future, sparking your fear for Lucien's safety. In response, you fashioned a lucky charm and handed it to him."
  },
  [140303] = {
    module_page_id = 2100,
    order_in_page = 3,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The next day, you were invited to Infinite's office to test Odyssey on the [c][f78585]Golden Apple 3[-][/c] system, while Lucien attended a neuroscience conference there. Frank Beale, the game developer rescued from the G.R. auction, greeted you. As you navigated the virtual streets of \"Loveland City,\" you marveled at the simulation's realism. But midway through, Frank approached with urgency, saying that there had been an unforeseen circumstance and that everyone needed to evacuate. While leaving, you encountered Lucien in the hallway, where a strange rift had materialized."
  },
  [140304] = {
    module_page_id = 2100,
    order_in_page = 4,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Lucien studied the rift, observing that it had begun to [c][f78585]affect[-][/c] reality as it created [c][f78585]shadowy duplicates[-][/c] of nearby people. He attempted to close the rift using gravity but to no avail. Suddenly, the body of a man caught in the rift became transparent. Lucien tried to grab him, but his hand passed through him like mist. Yet when you reached out, the Core [c][f78585]resonated[-][/c] powerfully, and for a split second, you saw massive [c][f78585]gears[-][/c] turning deep within the rift. Drawing on that surge of energy, you managed to grasp the man's arm and pull him back into reality. The Special Task Force then arrived, ushering people to safety. Lucien warned them that the rift had begun to change and could no longer be managed with the old protocols. As you both left Infinite, the memory of the gears and shadows lingered in your mind, filling you with unease. Lucien reassured you that every problem had a solution—it was only a matter of time."
  },
  [140305] = {
    module_page_id = 2100,
    order_in_page = 5,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 140306,
    module_to_module_delay = 0.5,
    module_delay = 14,
    module_desc = "Though the rift disappeared the next day, your anxiety did not. Sensing your lingering fear, Lucien suggested that the best way to alleviate it was to face the problem head-on. You described the strange vision you'd seen yesterday, in which he identified the creatures as \"[c][f78585]four-dimensional worms[-][/c],\" similar to those you had glimpsed at the ruins in Thousand Peaks. Lucien theorized that these worms could be linked to the comet, which marked the beginning of these rifts. Seeing your distress, Lucien pulled you into a gentle embrace, momentarily easing your worry. You asked to go with Lucien the next time he was going to study the rifts, to which he said that was his plan all along."
  },
  [140306] = {
    module_page_id = 2100,
    order_in_page = 6,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"Of course, delving into the unknown carries its risks. This isn't something I'm forcing on you. You have the right to say no.\"",
    role1 = 236000,
    role2 = 202101,
    role3 = 202201,
    module_role_zoom_rate = 0.5,
    module_remove = "0,-218",
    module_background_id = 1712,
    module_voice = "voice_125104_95.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [140307] = {
    module_page_id = 2100,
    order_in_page = 7,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "On the weekend, you accompanied Lucien to Ultima Bioresearch, where he had preserved a rift within one of the labs. Using the power of the Core, you managed to exert your influence on the rift. A small robot was deployed into the rift, recording data from its other side. During a break, Lucien surprised you with a limited-edition keychain, a small token to encourage you. In the end, you and Lucien worked together—using your power of the Core with his gravity Evol to seal the rift completely."
  },
  [140308] = {
    module_page_id = 2100,
    order_in_page = 8,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Buoyed by the experiment's success, Lucien expressed his desire to enter the rift himself. You recalled the future vision of his injury—a day now rapidly approaching—and grew anxious. Sensing your fear, Lucien promised to delay the mission by a week, and you insisted on going with him. Only after the day of your vision passed without incident did you breathe a sigh of relief. On the eve of your expedition, you met Lucien at the door, exchanging quiet goodnights. The next day, as you crossed the threshold, an overwhelming force pulled at your consciousness. In that instant, the gears flashed again in your mind. Suddenly, you found yourself inside a large [c][f78585]incubation pod[-][/c], pain rippling through your body. You struggled to make sense of your surroundings."
  },
  [140309] = {
    module_page_id = 2100,
    order_in_page = 9,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Emerging from the rift, Lucien realized with growing dread that you were gone. Instead of the expected 37 days, he found himself in Loveland City [c][f78585]74[-][/c] days ahead in the future. Frantically searching a computer for clues, he discovered that you might be at N.W. Without hesitation, he rushed there and wounded a researcher who was trying to stop him from saving you."
  },
  [140310] = {
    module_page_id = 2100,
    order_in_page = 10,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Lucien freed you from the pod, but the two of you were soon surrounded by N.W. operatives. As the battle escalated, Lucien was injured, and you were struck by a tranquilizer dart. Using Lucien's [c][f78585]Space-Folding Evol[-][/c], you two managed to escape into a storage room. Seeing Lucien's wound broke your heart, but he dismissed it with a comforting smile."
  },
  [140311] = {
    module_page_id = 2100,
    order_in_page = 11,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 140312,
    module_to_module_delay = 0.5,
    module_delay = 6,
    module_desc = "As you continued to flee using Lucien's Evol, he was slowly being pushed to the limit. Worried, you begged him to rest, but he refused, and you could only channel the power of the Core to help him. When you reached a park, Lucien finally laid you down on a bench and told you to rest if you're tired."
  },
  [140312] = {
    module_page_id = 2100,
