    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 3,
    module_to_module_delay = 0.5,
    module_desc = "\"Take a nap if you're tired. Pretend it's a bad dream. The next time you open your eyes... it'll all be over.\"",
    module_card_id = 52751,
    module_CG_zoom = 0.83,
    module_remove = "0,-200",
    module_voice = "voice_125108_31.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [140313] = {
    module_page_id = 2100,
    order_in_page = 13,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You wanted to stay awake, to see this journey through with him, but the tranquilizer's effects dragged you into unconsciousness. When you awoke, you found yourself alone in Lucien's home, and the door locked from the outside."
  },
  [140314] = {
