    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Later that night, Lucien carried you back to the bedroom and then made a call to schedule a \"[c][f78585]surgery[-][/c]\" for himself."
  },
  [140320] = {
    module_page_id = 2100,
    order_in_page = 20,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The next morning, you woke to find Lucien gone. A message awaited you on your phone—he had gone to an overseas lab to continue researching the rifts and hoped you would uncover the answers you were seeking."
  },
  [140401] = {
    module_page_id = 2101,
