    order_in_page = 2,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "With the research on rifts stalled, you returned to the familiar rhythm of everyday work. Late one night, as you were working overtime, the lights above your desk began to flicker, their pulses oddly rhythmic. Curious, you stepped out into the hallway. In the dim light of the company's lobby, you found Shaw sprawled across the sofa, resting."
  },
  [140456] = {
    module_page_id = 2101,
    order_in_page = 3,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "He had been absent for a long time, busy trying to repair the Dragonfly Eye. All you had received from him was a message saying that the repairs were \"almost complete.\""
  },
  [140457] = {
    module_page_id = 2101,
    order_in_page = 4,
