    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Without explaining much, Shaw stood up, took your hand, and insisted that you join him on an errand."
  },
  [140458] = {
    module_page_id = 2101,
    order_in_page = 5,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "You had countless questions for him, but Shaw deflected them with casual ease. The repaired Dragonfly Eye pulsed with a soft glow around Shaw's neck, filling you with a surge of hope that his troubles were finally over."
  },
  [140459] = {
    module_page_id = 2101,
    order_in_page = 6,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "When pressed further, Shaw revealed that before returning to Loveland City, he had taken on a task from [c][f78585]Infinite[-][/c] to locate Frank Beale, the game developer who had fled with the game data for [c][f78585]Odyssey[-][/c]."
  },
  [140460] = {
    module_page_id = 2101,
    order_in_page = 7,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Arriving at a crumbling old building, Shaw explained that a contact of his saw Frank here through a spatial rift."
  },
  [140461] = {
    module_page_id = 2101,
    order_in_page = 8,
    module_unlock_request = 315220,
    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Sure enough, Frank appeared, but he was a shadow of his former confident self—his face pale and haunted. Upon seeing you, Frank immediately urged you to end your collaboration with Infinite, accusing them of endangering people's lives."
  },
  [140462] = {
    module_page_id = 2101,
    order_in_page = 9,
