    module_unlock_request_desc = "Clear stage 52-20 to unlock",
    module_vol_id = 214,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Disillusioned and desperate, Frank had contemplated selling the tech overseas."
  },
  [140464] = {
