  [150102] = {
    module_page_id = 2102,
    order_in_page = 2,
    module_unlock_request = 315331,
    module_unlock_request_desc = "Clear stage 53-23 to unlock",
    module_entrance_unlock_request_cid = 3154,
    module_vol_id = 215,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "24, the Lighthouse's Remnant Intelligence delivered an urgent warning—[c][f78585]the World Trajectory Model[-][/c] was about to explode. The world's energy was spiraling into chaotic [c][f78585]expansion[-][/c], and a disaster was looming on the horizon. He sought your help, hoping you had a solution, but you had none.\nMeanwhile, your responsibilities piled up. Infinite's launch of [c][f78585]Odyssey[-][/c], preparations for Kiro's concert, and countless other tasks weighed you down. In the chaos, you nearly forgot today was Shaw's music festival rehearsal until his call reminded you. That evening, you rushed to the venue."
  },
  [150103] = {
    module_page_id = 2102,
    order_in_page = 3,
    module_unlock_request = 315331,
    module_unlock_request_desc = "Clear stage 53-23 to unlock",
    module_entrance_unlock_request_cid = 3154,
    module_vol_id = 215,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "At rehearsal, you and Shaw laughed and joked, enjoying the rare peace. Loveland City had been unusually quiet, but Shaw hinted at knowing something about the world's changes. Yet, no matter how you pressed him, he refused to say more."
  },
  [150104] = {
    module_page_id = 2102,
    order_in_page = 4,
    module_unlock_request = 315331,
    module_unlock_request_desc = "Clear stage 53-23 to unlock",
    module_entrance_unlock_request_cid = 3154,
    module_vol_id = 215,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "As soon as you arrived at the beach venue, unease settled in. The [c][f78585]amount of visitors[-][/c] was far beyond the site's capacity. You tried to move with the flow, making your way toward the backstage area when a sharp scream cut through the air. Before you or Shaw could react, an immense tidal wave crashed down, swallowing you both whole."
  },
  [150105] = {
    module_page_id = 2102,
    order_in_page = 5,
    module_unlock_request = 315331,
    module_unlock_request_desc = "Clear stage 53-23 to unlock",
    module_entrance_unlock_request_cid = 3154,
    module_vol_id = 215,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 150106,
    module_to_module_delay = 0.5,
    module_delay = 3,
    module_desc = "You woke up [c][f78585]three days in the past[-][/c]. Dazed, you assumed it was just a dream until Shaw called, telling you to wait for him at the company. When you met, he pulled you into a trembling embrace."
  },
  [150106] = {
    module_page_id = 2102,
    order_in_page = 6,
    module_unlock_request = 315331,
    module_unlock_request_desc = "Clear stage 53-23 to unlock",
    module_entrance_unlock_request_cid = 3154,
