    role1 = 784000,
    role2 = 712103,
    role3 = 712201,
    module_role_zoom_rate = 0.5,
    module_remove = "0,-221",
    module_background_id = 1651,
    module_voice = "voice_9100002_82.mp3",
    module_voice_species = 0,
    module_voice_delay = 0.5
  },
  [150107] = {
    module_page_id = 2102,
    order_in_page = 7,
    module_unlock_request = 315331,
    module_unlock_request_desc = "Clear stage 53-23 to unlock",
    module_entrance_unlock_request_cid = 3154,
    module_vol_id = 215,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Then, he explained that he had used the [c][f78585]Dragonfly Eye[-][/c] and Core's power to rewind time. That meant the [c][f78585]tsunami[-][/c] wasn't a nightmare; it was a disaster set to strike in three days. After a moment of silence, you made your first move—postpone the festival to keep people away from the disaster."
  },
  [150108] = {
    module_page_id = 2102,
    order_in_page = 8,
    module_unlock_request = 315331,
    module_unlock_request_desc = "Clear stage 53-23 to unlock",
    module_entrance_unlock_request_cid = 3154,
    module_vol_id = 215,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The announcement was met with confusion and backlash. While enjoying hotpot with the members of Isolated, they also expressed their dismay. Online, angry voices lashed out, furious over the sudden postponement. But Shaw refused to explain, and he wouldn't let you explain either. The dinner ended on a sour note. As you left, Jensen pulled you aside, asking you to tell Shaw that he should trust his teammates more."
  },
  [150109] = {
    module_page_id = 2102,
    order_in_page = 9,
    module_unlock_request = 315331,
    module_unlock_request_desc = "Clear stage 53-23 to unlock",
    module_entrance_unlock_request_cid = 3154,
    module_vol_id = 215,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "On the third day, you and Shaw braced for the worst, but the tsunami never came. Shaw told you that you should just pretend the whole thing never happened, and you agreed. Yet, as you returned to the Live House, you ran into a group of hostile rock band fans looking for trouble."
  },
