  },
  [150311] = {
    module_page_id = 2104,
    order_in_page = 11,
    module_unlock_request = 9100126,
    module_unlock_request_desc = "Clear Yesterday's Shadow 54-21 to unlock",
    module_entrance_unlock_request_cid = 3154,
    module_vol_id = 215,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 150312,
    module_to_module_delay = 0.5,
    module_delay = 2,
    module_desc = "To finalize the promotional details, you visited the renovation site of the underground commercial district, where you found Victor inspecting the construction. During your conversation, you learned that he had long been planning to integrate disaster prevention facilities into this area during the [c][f78585]commercial district renovation[-][/c]."
  },
  [150312] = {
    module_page_id = 2104,
    order_in_page = 12,
    module_unlock_request = 9100126,
    module_unlock_request_desc = "Clear Yesterday's Shadow 54-21 to unlock",
    module_entrance_unlock_request_cid = 3154,
    module_vol_id = 215,
    module_season_id = 2,
    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"Preventing disaster before it happens is far more meaningful than fixing things afterward.\"",
    role1 = 1166000,
    role2 = 101101,
    role3 = 101202,
    module_role_zoom_rate = 0.5,
    module_remove = "0,-210",
