    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"I'm here, so there's nothing you need to be afraid of.\"",
    role1 = 1167000,
    role2 = 102104,
    role3 = 102203,
    role5 = 1167402,
