  },
  [150321] = {
    module_page_id = 2104,
    order_in_page = 21,
    module_unlock_request = 9100126,
    module_unlock_request_desc = "Clear Yesterday's Shadow 54-21 to unlock",
    module_entrance_unlock_request_cid = 3154,
    module_vol_id = 215,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "To close the rift, you and Victor headed to the tallest nearby building. With unwavering determination, you unleashed your power into the rift, successfully slowing the advance of the seawater. As you feel increasingly drained of strength, a vast [c][f78585]network of gears[-][/c] appeared before you. At that moment, you realized—it was the very place where you had once thrust the [c][f78585]golden dagger[-][/c] to stop the apocalypse."
  },
  [150322] = {
    module_page_id = 2104,
    order_in_page = 22,
    module_unlock_request = 9100126,
    module_unlock_request_desc = "Clear Yesterday's Shadow 54-21 to unlock",
    module_entrance_unlock_request_cid = 3154,
    module_vol_id = 215,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "The gears seemed to call out to you, drawing you in. With sheer willpower, you resisted their pull. Suddenly, a white door emerged before you."
  },
  [150323] = {
