    module_unlock_request_desc = "Clear stage 58-15 to unlock",
    module_vol_id = 216,
    module_season_id = 2,
    module_type = 2,
    module_to_module_delay = 0.5,
    module_desc = "\"Even if I'm not there, I'll make sure it goes away.\"",
    role1 = 3146000,
    role2 = 702101,
    role3 = 302205,
    module_role_zoom_rate = 0.5,
    module_remove = "0,-200",
    module_background_id = 1121,
