  },
  [160317] = {
    module_page_id = 2109,
    order_in_page = 1,
    module_unlock_request = 315815,
    module_unlock_request_desc = "Clear stage 58-15 to unlock",
    module_vol_id = 216,
    module_season_id = 2,
    module_type = 1,
    module_to_module_delay = 0.5,
    module_desc = "Hephaestus submitted a report to Kiro detailing the mental and physical changes observed in [c][f78585]users of the mechanical box[-][/c], with most having shown signs of deterioration. When Kiro saw your name on the list, his heart skipped a beat, but Hephaestus calmly explained that the [c][f78585]Queen[-][/c] was different, and so far, there were no symptoms."
  },
