  },
  [160417] = {
    module_page_id = 2110,
    order_in_page = 1,
    module_unlock_request = 315815,
    module_unlock_request_desc = "Clear stage 58-15 to unlock",
    module_vol_id = 216,
    module_season_id = 2,
    module_type = 1,
    module_connect_id = 160418,
    module_to_module_delay = 0.5,
    module_delay = 7.5,
    module_desc = "You sat together at the tunnel entrance, listening to the rain. Gavin was still preoccupied with thoughts of Cody. You admitted you were also angry and regretted not joining him in-game to give the boy a piece of your mind. Gavin confessed he was frustrated—not because of what Cody had said, but because he never got the chance to say what he needed to. The boy had vanished before he could reach him. Gavin believed that despite the imperfections of [c][f78585]the real world[-][/c], having you in it will always make it better than any virtual reality."
  },
